PRAGMA foreign_keys = ON;

INSERT OR IGNORE INTO help_articles(id,slug,module,title,summary,audience,body_markdown) VALUES
('help-finance-control','finance-control','FINANCE','Finance Control Center','Zero-maintenance finance architecture, reconciliation flow, exception management and money-movement controls.','OWNER_EXECUTIVE','# Finance Control Center\n\nPurpose: give the owner a low-maintenance management view without turning WorkflowOS into the accounting ledger.\n\nSystem roles:\n1. Shopify Payments = primary customer payment processing.\n2. Business bank = cash custody and reserves.\n3. QuickBooks Online = official accounting ledger.\n4. Shopify Tax = supported transaction-level sales-tax automation.\n5. WorkflowOS = budget, cash forecast, margin, approvals, reconciliation status and exception control.\n\nSafety rule: AI may read, analyze, forecast and prepare recommendations. It must not autonomously change payout destinations, transfer money, add bank accounts or perform material refunds.\n\nOperating principle: normal transactions reconcile automatically; the owner reviews exceptions and consequential approvals.\n\nStatus: architecture baseline only until each external system is explicitly connected and verified.');
